# Export the char-bigram micro-LM (see junk_gate.py CharBigramLM) as a C++
# header for the plugin's content gate. 27x27 negative log2 probabilities,
# a-z + space (everything else folds to space). Trained on Brown news — the
# specific corpus barely matters; the table measures English-likeness.
from pathlib import Path

from junk_gate import CharBigramLM

OUT = Path(__file__).parent.parent / "src" / "core" / "bigram_en.h"

lm = CharBigramLM()
nll = -lm.logp  # bits, all positive

lines = [
    "// SkinnerBox++ — English char-bigram cost table (bits), generated by",
    "// experiments/export_bigram.py from the NLTK Brown corpus (news). 27x27:",
    "// a-z + space; non-alpha input folds to space. Regenerate, don't edit.",
    "// This file is part of SkinnerBox++, released under the GNU GPL v3 or later.",
    "",
    "#pragma once",
    "",
    "namespace sbpp {",
    "",
    "// kBigramBits[prev][next]: -log2 P(next | prev).",
    "inline constexpr float kBigramBits[27][27] = {",
]
for i in range(27):
    row = ", ".join(f"{nll[i, j]:.3f}f" for j in range(27))
    lines.append(f"    {{{row}}},")
lines += ["};", "", "} // namespace sbpp", ""]
OUT.write_text("\n".join(lines), encoding="utf-8", newline="\n")
print(f"wrote {OUT}")
